{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, count(*) n, round(quantile_cont(CAST(c.duration AS DOUBLE)-CAST(s.duration AS DOUBLE),0.5)/1e6,1) gap_med_ms, round(quantile_cont(CAST(c.duration AS DOUBLE),0.5)/1e6,1) call_med_ms, round(quantile_cont(CAST(s.duration AS DOUBLE),0.5)/1e6,1) srv_med_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server' UNION ALL SELECT 'norm', count(*), round(quantile_cont(CAST(c.duration AS DOUBLE)-CAST(s.duration AS DOUBLE),0.5)/1e6,1), round(quantile_cont(CAST(c.duration AS DOUBLE),0.5)/1e6,1), round(quantile_cont(CAST(s.duration AS DOUBLE),0.5)/1e6,1) FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server'",
          "claim": "Travel-plan's POST calls to seat-service take about 2.3 s longer on the client side than the seat server span (~17 ms), versus ~3 ms normally."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, attr_source, attr_destination, round(sum(sum)/sum(count),4) avg_s, sum(count) n FROM abnormal_metrics_histogram WHERE metric='hubble_http_request_duration_seconds' AND attr_source LIKE '%travel-plan%' AND attr_destination LIKE '%seat%' GROUP BY ALL UNION ALL SELECT 'norm', attr_source, attr_destination, round(sum(sum)/sum(count),4), sum(count) FROM normal_metrics_histogram WHERE metric='hubble_http_request_duration_seconds' AND attr_source LIKE '%travel-plan%' AND attr_destination LIKE '%seat%' GROUP BY ALL",
          "claim": "Hubble wire-level HTTP duration travel-plan→seat stays ~30 ms in both periods, so the extra delay is not on the network."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, round(quantile_cont(CAST(duration AS DOUBLE),0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','ts-travel-plan-service') AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, count(*), round(quantile_cont(CAST(duration AS DOUBLE),0.95)/1e6,1) FROM normal_traces WHERE service_name IN ('ts-ui-dashboard','ts-travel-plan-service') AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL ORDER BY 2,3,1",
          "claim": "Travel-plan's travelPlan endpoints run ~20-24 s p95 at the user-facing ui-dashboard versus ~0.8-1 s normally."
        }
      ]
    }
  ]
}
